/** A signed-in user as auth sees it */
export interface AuthUser {
	/** User id */
	id: string;
	/** Verified email from the auth provider */
	email: string;
	/** Avatar URL */
	image: string;
}

/** Profile returned by an OAuth provider after sign in */
export interface AuthProfile {
	/** Verified email, used to match an existing user */
	email: string;
	/** Avatar URL from the provider */
	image: string;
}

/** A login session as auth sees it */
export interface AuthSession {
	/** SHA-256 hash of the session cookie token */
	id: string;
	/** Id of the user who owns the session */
	userId: string;
	/** When the session stops being valid */
	expiresAt: Date;
}

/** Database calls auth needs, so any database can back it */
export interface AuthDb {
	/** Saves a new session */
	createSession(session: AuthSession): Promise<void>;
	/** Finds a session by id, or returns `null` */
	findSession(id: string): Promise<AuthSession | null>;
	/** Moves a session's expiry date */
	updateSessionExpiry(id: string, expiresAt: Date): Promise<void>;
	/** Deletes a session by id */
	deleteSession(id: string): Promise<void>;
	/** Finds a user by id, or returns `null` */
	findUser(id: string): Promise<AuthUser | null>;
	/** Finds the user with the profile's email and updates it, or creates one */
	upsertUser(profile: AuthProfile): Promise<AuthUser>;
}

/** Access token returned by an OAuth provider */
export interface AuthProviderToken {
	/** Access token for the provider's API */
	value: string;
	/** Scopes the user granted */
	scopes: string[];
	/** When the token expires, if the provider says */
	expiresAt?: Date;
}

/** Result of exchanging a callback code, with an error message or the token and profile */
export type AuthProviderResult = { error: true; data: string } | { error: false; data: { token: AuthProviderToken; user: AuthProfile & { id: string } } };

/** OAuth provider steps, so the sign in and callback routes work with any provider */
export interface AuthProvider {
	/** Provider name, such as `google` */
	name: string;
	/** Builds the provider's sign in URL from the state and PKCE verifier */
	createAuthorizationURL(state: string, codeVerifier: string): URL;
	/** Exchanges the callback code for a token and the user's verified profile */
	validateAuthorizationCode(code: string, codeVerifier: string): Promise<AuthProviderResult>;
}

import { randomBytes, createHash } from "crypto";
import { dev } from "$app/env";
import { authDb } from "./db.js";
import type { AuthSession, AuthUser } from "./types.js";
import type { RequestEvent } from "@sveltejs/kit";
const DAY = 1000 * 60 * 60 * 24;

/** Sets a cookie; `expires` wins over `maxAge`, and the default lifetime is 10 minutes */
export function setCookie(event: RequestEvent, name: string, value: string, options?: { maxAge?: number; expires?: Date }) {
	event.cookies.set(name, value, {
		path: "/",
		// Hide auth cookies from page scripts, and send them only over HTTPS outside the dev server.
		httpOnly: true,
		secure: !dev,
		maxAge: options?.maxAge !== undefined ? options.maxAge : options?.expires !== undefined ? undefined : 60 * 10,
		expires: options?.expires,
		sameSite: "lax",
	});
}

/** Creates a random URL-safe token, used for the OAuth state, the PKCE verifier, and session tokens */
export function generateToken() {
	return randomBytes(32).toString("base64url");
}

/** Creates a 30-day session for the user and sets its token as the `session` cookie */
export async function createAndSetSession(event: RequestEvent, userId: string) {
	const token = generateToken();
	// Store only the hash, so a leaked database cannot be used to sign in.
	const session: AuthSession = { id: hashToken(token), userId, expiresAt: new Date(Date.now() + DAY * 30) };
	await authDb.createSession(session);
	setCookie(event, "session", token, { expires: session.expiresAt });
	return session;
}

/** Returns the session and user for a `session` cookie token, refreshing sessions that expire within 15 days */
export async function validateSessionToken(event: RequestEvent, token: string): Promise<SessionValidationResult> {
	const sessionId = hashToken(token);
	const session = await authDb.findSession(sessionId);
	// If no session matches the token: treat the user as signed out.
	if (!session) return { session: null, user: null };

	const now = Date.now();
	// If the session expired: delete it and the cookie.
	if (now >= session.expiresAt.getTime()) {
		await authDb.deleteSession(sessionId);
		event.cookies.delete("session", { path: "/" });
		return { session: null, user: null };
	}

	// If the session expires within 15 days: push the expiry 30 days from now.
	if (now >= session.expiresAt.getTime() - DAY * 15) {
		session.expiresAt = new Date(now + DAY * 30);
		await authDb.updateSessionExpiry(sessionId, session.expiresAt);
	}

	const user = await authDb.findUser(session.userId);
	// If the user was deleted: drop the orphaned session.
	if (!user) {
		await authDb.deleteSession(sessionId);
		event.cookies.delete("session", { path: "/" });
		return { session: null, user: null };
	}
	return { session, user };
}

/** Deletes the signed-in user's session and its cookie */
export async function deleteSession(event: RequestEvent) {
	// If no one is signed in: skip the database call.
	if (!event.locals.sessionData) return;
	await authDb.deleteSession(event.locals.sessionData.id);
	event.cookies.delete("session", { path: "/" });
}

/** Hashes a session token into the id stored in the database */
function hashToken(token: string) {
	return createHash("sha256").update(token).digest("hex");
}

/** Session and user for a valid token, or both `null` */
export type SessionValidationResult = { session: AuthSession; user: AuthUser } | { session: null; user: null };

import { validateSessionToken } from "./session.js";
import type { Handle } from "@sveltejs/kit/hooks";

/** Loads the signed-in user into `locals` and adds the `dark` class to `<body>` on the server */
export const handle: Handle = async ({ event, resolve }) => {
	const token = event.cookies.get("session");
	// If there is a session cookie: load its session and user.
	if (token) {
		const { session, user } = await validateSessionToken(event, token);
		event.locals.userData = user;
		event.locals.sessionData = session;
	} else {
		event.locals.userData = null;
		event.locals.sessionData = null;
	}

	// If it is a page request: add the `dark` class to <body> from the theme cookie.
	if (event.request.method === "GET" && event.route.id !== null) {
		event.locals.isDarkMode = event.cookies.get("theme") === "dark";
		return await resolve(event, { transformPageChunk: ({ html }) => (event.locals.isDarkMode ? html.replace("<body ", '<body class="dark" ') : html) });
	}
	return await resolve(event);
};

import { redirect } from "@sveltejs/kit";
import { deleteSession } from "#lib/server/auth/session.js";
import type { RequestHandler } from "./$types";

/** Signs the user out and goes home */
export const GET: RequestHandler = async (event) => {
	await deleteSession(event);
	return redirect(302, "/");
};
